-- ---------------------------------------------------------------------------
-- 1. The tenant role. NOLOGIN: it is reached only by SET LOCAL ROLE inside a
--    transaction that has already established tenant context. NOINHERIT so
--    it never picks up the migration role's privileges by membership.
-- ---------------------------------------------------------------------------
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_tenant') THEN
    CREATE ROLE app_tenant NOLOGIN NOINHERIT NOBYPASSRLS NOSUPERUSER NOCREATEDB NOCREATEROLE;
  END IF;
  -- The connection role must be a member of the tenant role to SET ROLE to it.
  EXECUTE format('GRANT app_tenant TO %I', current_user);
END $$;

GRANT USAGE ON SCHEMA public TO app_tenant;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO app_tenant;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO app_tenant;
-- Prisma's migration ledger is not application data and is not classified;
-- the blanket grant above must not reach it. Conditional because Prisma's
-- SHADOW database (used by `migrate dev` to compute diffs) replays the
-- migration files without creating the ledger table.
DO $$ BEGIN
  IF to_regclass('public._prisma_migrations') IS NOT NULL THEN
    EXECUTE 'REVOKE ALL ON "_prisma_migrations" FROM app_tenant';
  END IF;
END $$;
-- Tables created by later migrations get the same grants; their policies are
-- still their own migration's job, and the coverage test fails until they exist.
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO app_tenant;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT USAGE, SELECT ON SEQUENCES TO app_tenant;

-- ---------------------------------------------------------------------------
-- 2. Context accessors. STABLE so the planner evaluates them once per
--    statement. current_setting(name, TRUE) never raises; NULLIF folds the
--    empty string a recycled connection reports into NULL, and NULL is equal
--    to nothing, so both "never set" and "set and cleared" match no row.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION app_current_user_id() RETURNS text
  LANGUAGE sql STABLE PARALLEL SAFE
  AS $$ SELECT NULLIF(current_setting('app.current_user_id', TRUE), '') $$;

CREATE OR REPLACE FUNCTION app_current_organization_id() RETURNS text
  LANGUAGE sql STABLE PARALLEL SAFE
  AS $$ SELECT NULLIF(current_setting('app.current_organization_id', TRUE), '') $$;

-- The organisations the current user is an ACCEPTED, not-removed member of.
-- SECURITY DEFINER so the Membership read inside it is not itself subject to
-- the Membership policy, which would otherwise recurse (PostgreSQL refuses a
-- policy that references its own table). Owned by the migration role, whose
-- unconditional policy below is what the definer context relies on.
CREATE OR REPLACE FUNCTION app_member_organization_ids() RETURNS text[]
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = public
  AS $$
    SELECT COALESCE(array_agg(m."organizationId"), ARRAY[]::text[])
      FROM "Membership" m
     WHERE m."userId" = NULLIF(current_setting('app.current_user_id', TRUE), '')
       AND m."acceptedAt" IS NOT NULL
       AND m."removedAt" IS NULL
  $$;

REVOKE ALL ON FUNCTION app_current_user_id() FROM PUBLIC;
REVOKE ALL ON FUNCTION app_current_organization_id() FROM PUBLIC;
REVOKE ALL ON FUNCTION app_member_organization_ids() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app_current_user_id() TO app_tenant;
GRANT EXECUTE ON FUNCTION app_current_organization_id() TO app_tenant;
GRANT EXECUTE ON FUNCTION app_member_organization_ids() TO app_tenant;

