DROP POLICY IF EXISTS tenant_access ON "WebhookDelivery";
DROP POLICY IF EXISTS tenant_read ON "WebhookDelivery";
DO $$ BEGIN EXECUTE format('CREATE POLICY system_full_access ON "WebhookDelivery" TO %I USING (true) WITH CHECK (true)', current_user); END $$;
DROP POLICY IF EXISTS tenant_update ON "WebhookDelivery";
CREATE POLICY tenant_access ON "WebhookDelivery" TO app_tenant USING (EXISTS (SELECT 1 FROM "WebhookEndpoint" p WHERE p."id" = "WebhookDelivery"."endpointId")) WITH CHECK (EXISTS (SELECT 1 FROM "WebhookEndpoint" p WHERE p."id" = "WebhookDelivery"."endpointId"));

-- WebhookEndpoint (user)
ALTER TABLE "WebhookEndpoint" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "WebhookEndpoint" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS system_full_access ON "WebhookEndpoint";
DROP POLICY IF EXISTS tenant_access ON "WebhookEndpoint";
DROP POLICY IF EXISTS tenant_read ON "WebhookEndpoint";
DO $$ BEGIN EXECUTE format('CREATE POLICY system_full_access ON "WebhookEndpoint" TO %I USING (true) WITH CHECK (true)', current_user); END $$;
DROP POLICY IF EXISTS tenant_update ON "WebhookEndpoint";
CREATE POLICY tenant_access ON "WebhookEndpoint" TO app_tenant USING ("userId" = app_current_user_id()) WITH CHECK ("userId" = app_current_user_id());

-- WebhookEvent (system)
ALTER TABLE "WebhookEvent" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "WebhookEvent" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS system_full_access ON "WebhookEvent";
DROP POLICY IF EXISTS tenant_access ON "WebhookEvent";
DROP POLICY IF EXISTS tenant_read ON "WebhookEvent";
DO $$ BEGIN EXECUTE format('CREATE POLICY system_full_access ON "WebhookEvent" TO %I USING (true) WITH CHECK (true)', current_user); END $$;
DROP POLICY IF EXISTS tenant_update ON "WebhookEvent";
-- (no tenant policy: a forced table with no policy for app_tenant denies every command)

-- ---------------------------------------------------------------------------
-- 4. Managed-PostgreSQL hygiene. Supabase exposes the public schema over its
--    REST gateway to the anon and authenticated roles, with default grants on
--    new tables. Nothing in this application is served that way, so where
--    those roles exist their access is revoked outright. RLS being enabled
--    everywhere above already denies them (no policy names them); this makes
--    the intent explicit rather than incidental.
-- ---------------------------------------------------------------------------
DO $$
DECLARE r text;
BEGIN
  FOREACH r IN ARRAY ARRAY['anon', 'authenticated'] LOOP
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN
      EXECUTE format('REVOKE ALL ON ALL TABLES IN SCHEMA public FROM %I', r);
      EXECUTE format('REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM %I', r);
      EXECUTE format('REVOKE ALL ON ALL FUNCTIONS IN SCHEMA public FROM %I', r);
      EXECUTE format('ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON TABLES FROM %I', r);
      EXECUTE format('ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON SEQUENCES FROM %I', r);
      EXECUTE format('ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON FUNCTIONS FROM %I', r);
    END IF;
  END LOOP;
END $$;
